import{_ as e,o as r,c as t,x as o}from"./chunks/framework.DzQQ_lrg.js";const f=JSON.parse('{"title":"飓风伊恩的预报锥：画的是中心的去向，潮水有多高要另外问","description":"从美国国家飓风中心的事后报告和2022年预报锥定义，看预报锥回答的是哪个问题，哪些问题要靠别的材料回答。","frontmatter":{"title":"飓风伊恩的预报锥：画的是中心的去向，潮水有多高要另外问","description":"从美国国家飓风中心的事后报告和2022年预报锥定义，看预报锥回答的是哪个问题，哪些问题要靠别的材料回答。","kind":"真实案例","source_type":"官方事后报告与预报产品说明","concepts":["representation-loss"]},"headers":[],"relativePath":"cases/representation-hurricane-cone.md","filePath":"cases/representation-hurricane-cone.md"}'),n={name:"cases/representation-hurricane-cone.md"};function i(l,a,h,s,c,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="飓风伊恩的预报锥-画的是中心的去向-潮水有多高要另外问" tabindex="-1">飓风伊恩的预报锥：画的是中心的去向，潮水有多高要另外问 <a class="header-anchor" href="#飓风伊恩的预报锥-画的是中心的去向-潮水有多高要另外问" aria-label="Permalink to &quot;飓风伊恩的预报锥：画的是中心的去向，潮水有多高要另外问&quot;">​</a></h1><p>2022年9月28日19时05分（协调世界时，当地时间15时05分），飓风伊恩以四级强度在美国佛罗里达州西南部的Cayo Costa岛登陆，约一个半小时后，中心又在Punta Gorda附近登陆。美国国家飓风中心（NHC）的事后报告把它带来的风暴潮称为灾难性的。<a href="https://www.nhc.noaa.gov/data/tcr/AL092022_Ian.pdf" target="_blank" rel="noreferrer">NHC伊恩飓风报告，第1、4页</a></p><p>报告提到，伊恩期间NHC网站的访问多数落在图形产品上，预报锥图是其中之一。<a href="https://www.nhc.noaa.gov/data/tcr/AL092022_Ian.pdf" target="_blank" rel="noreferrer">报告第18页</a> 在伊恩的记录里，预报锥回答了什么，又有什么本来就不由它回答？</p><h2 id="预报锥画的是什么" tabindex="-1">预报锥画的是什么 <a class="header-anchor" href="#预报锥画的是什么" aria-label="Permalink to &quot;预报锥画的是什么&quot;">​</a></h2><p>按NHC在2022年公布的定义，预报锥表示热带气旋<strong>中心</strong>的可能路径：沿预报路径在12、24、36小时等时点各取一个圆，把这些圆扫过的区域围起来。圆的大小取自此前五年的官方预报误差，使其中三分之二落在圆内。2022年用的是2017—2021年的统计，大西洋的半径在12小时为26海里，48小时为67海里，120小时为200海里。同一页还说，按此前五年的预报，整条路径始终留在锥内的情形约占60%—70%。<a href="https://web.archive.org/web/20220926140803/https://www.nhc.noaa.gov/aboutcone.shtml" target="_blank" rel="noreferrer">NHC预报锥定义，2022年9月26日存档</a></p><p>这个定义只涉及中心的位置，没有涉及风、雨和潮水会影响到哪里。锥的宽窄来自历史上的预报误差，同一年、同一海域的每场风暴都用同一组半径；三分之二这个比例也说明，中心可能落在圆外。</p><h2 id="报告和当期讨论记录了什么" tabindex="-1">报告和当期讨论记录了什么 <a class="header-anchor" href="#报告和当期讨论记录了什么" aria-label="Permalink to &quot;报告和当期讨论记录了什么&quot;">​</a></h2><p>NHC在报告中回顾自己的路径预报：误差主要出在垂直于路径的方向，各期预报一贯偏西，西南佛罗里达的确切登陆点因此难以预报；但报告称，所有预报周期的预报锥都包含了登陆位置。报告为这句话配的图，画出的是第12至22号通告（advisory）中选出的若干期预报锥和Cayo Costa登陆点。<a href="https://www.nhc.noaa.gov/data/tcr/AL092022_Ian.pdf" target="_blank" rel="noreferrer">报告第15页；图27在第67页</a></p><p>同一份报告记录的潮水，在很短的距离内相差悬殊。Fort Myers Beach码头的水位传感器测到高出平均高高潮位（MHHW，报告称之为正常高潮线）12.70英尺的水位，是该监测网的最高读数；不到30英里外，Punta Gorda以南的Pirate Harbor只测到4.47英尺。再往北，从Port Charlotte、Englewood到Tampa Bay，多数传感器因离岸风没有测到风暴潮，Tampa Bay的水位还退到了正常以下。报告说，最严重的风暴潮在横跨中心路径的方向上有“急剧梯度”，这类差别显示了风暴潮对风暴确切路径的敏感。<a href="https://www.nhc.noaa.gov/data/tcr/AL092022_Ian.pdf" target="_blank" rel="noreferrer">报告第8—9、16页</a></p><p>潮水会有多高，由另一套产品回答。对Fort Myers Beach，风暴潮监视和警告分别在热带风暴级大风到达前48小时和30小时发布。这里的峰值风暴潮预报起初是地面以上4—7英尺，9月27日上午随预报路径南移升到8—12英尺，28日上午又因探测飞机发现伊恩增强而上调，最终为12—18英尺。报告认为这个范围涵盖了传感器测到的峰值，也与它事后分析的地面以上10—15英尺一致；预报和分析从地面起算，传感器读数从平均高高潮位起算，报告只在紧邻海岸处把两者近似对照。<a href="https://www.nhc.noaa.gov/data/tcr/AL092022_Ian.pdf" target="_blank" rel="noreferrer">报告第8、15—16页</a></p><p>风暴潮警告发布时北至Anclote River，包括Tampa Bay。由于路径南移，Englewood以北的警告没有兑现。NHC在报告中认为，警告阶段（危险状况出现前36小时以内）的路径不确定性足以支持这样大范围的警告，因为路径只要稍稍北移，这次没有进水的地方就可能出现极端风暴潮；报告没有展示这一情景。<a href="https://www.nhc.noaa.gov/data/tcr/AL092022_Ian.pdf" target="_blank" rel="noreferrer">报告第16页</a></p><p>登陆前一天的两期预报讨论都提醒使用者不要只盯着确切路径：路径还可能调整，强风、风暴潮和降雨的危害也会延伸到离中心很远的地方。讨论还请居民听从当地官员的建议和撤离命令。<a href="https://www.nhc.noaa.gov/archive/2022/al09/al092022.discus.018.shtml" target="_blank" rel="noreferrer">第18号预报讨论</a>、<a href="https://www.nhc.noaa.gov/archive/2022/al09/al092022.discus.020.shtml" target="_blank" rel="noreferrer">第20号预报讨论</a></p><h2 id="从这里读懂一个区别" tabindex="-1">从这里读懂一个区别 <a class="header-anchor" href="#从这里读懂一个区别" aria-label="Permalink to &quot;从这里读懂一个区别&quot;">​</a></h2><p>《Xikari-条件结构与转化论》讲尺度变换时有一项要求，适合用来读预报锥：“每项充分性判断还须指明目标查询或任务族、期限、环境和允许操作”。<a href="/xi-kari-skill/handbook/theory/part-03.html#section-3-4">阅读原文：§3.4</a> 预报锥的发布者写明了它的目标查询：中心在未来各时点的可能位置，把握程度按历史误差的三分之二来定。对这个问题，NHC的评价是登陆位置始终在锥内。</p><p>“某一段海岸的潮水会有多高”是另一个查询。预报锥画的是路径的不确定范围；而按报告的判断，警告阶段的路径还不确定，只要稍稍北移，这次保持干燥的地方就可能出现极端风暴潮。可以这样理解：落在同一个锥里的不同路径，对应着同一处海岸很不一样的潮水，只看预报锥分不开它们。原文的F1用形式语言说的是这类限制：“同一表示不能合并当前任务必须给出不同答案的状态”。<a href="/xi-kari-skill/handbook/theory/part-04.html#section-4-18-1">阅读原文：§4.18.1</a> 这里是借F1来读材料，不是检验F1：F1是在写明状态域、表示和目标的数学对象里成立的命题，本页没有为伊恩写出这些对象，报告里也没有“锥相同而潮水不同”的成对记录。</p><p>NHC没有让预报锥去回答潮水问题，而是另发风暴潮监视、警告和峰值预报。原文的说法是：“结构表示应保留哪些区别，取决于所问任务及允许作用于对象的操作”。<a href="/xi-kari-skill/handbook/theory/part-04.html#section-4-19">阅读原文：§4.19</a> 中心路径、风暴潮、强风和降雨是不同的任务，可以各有各的表示。</p><p>谁该撤离，预报锥没有回答；讨论请居民听从的是当地官员的建议和撤离命令。一种表示能回答什么，与谁可以针对哪个对象、采取什么动作、在什么地域和期限内作决定，原文分开处理。<a href="/xi-kari-skill/handbook/theory/part-14.html#section-14-6">阅读原文：§14.6</a></p><h2 id="这份材料能说明到哪里" tabindex="-1">这份材料能说明到哪里 <a class="header-anchor" href="#这份材料能说明到哪里" aria-label="Permalink to &quot;这份材料能说明到哪里&quot;">​</a></h2><p>本页依据NHC的事后报告、当期预报讨论和2022年的产品定义，帮助辨认一种表示是为哪个问题而做。它不说明预报锥没有用，也不说明路径预报没有误差；预报锥始终包含登陆位置、大范围警告有必要，这两点都是NHC对自己工作的评价。这些材料没有记录公众怎样理解预报锥，这里不据此推断任何人的判断或撤离决定。</p><p>读伊恩的预报锥要用2022年的定义。预报锥的半径按最近五年的误差逐年更新，NHC网站现在的定义页给出的已是2026年的数值（依据2021—2025年的误差，大西洋48小时为62海里）。<a href="https://www.nhc.noaa.gov/aboutcone.shtml" target="_blank" rel="noreferrer">NHC预报锥定义，当前页面</a></p><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><ol><li><p><strong>登陆位置始终在预报锥内，能不能说Fort Myers Beach的风暴潮风险已经由预报锥回答了？</strong></p><p>不能。锥画的是中心的可能路径。这里的潮水会有多高，由风暴潮监视、警告和峰值预报回答，这项预报随路径和强度的变化从4—7英尺改到了12—18英尺。</p></li><li><p><strong>Englewood以北的风暴潮警告没有兑现，能不能说警告发错了？</strong></p><p>不能直接这样说。没有兑现是因为路径南移；警告该不该发，要看发布时的路径不确定性。NHC自己的评价是应当发，但它所说的北移情景报告没有展示。预报有没有误差、警告是否合理，是两个问题。</p></li><li><p><strong>这份材料算不算对F1的一次现实检验？</strong></p><p>不算。F1是数学对象里的条件命题；这里没有写出状态域、表示和目标，也没有成对的记录。材料只帮助看清F1所说的那类限制在现实中是什么样子。</p></li></ol><h2 id="对照概念与原文" tabindex="-1">对照概念与原文 <a class="header-anchor" href="#对照概念与原文" aria-label="Permalink to &quot;对照概念与原文&quot;">​</a></h2><ul><li><a href="/xi-kari-skill/handbook/concepts/representation.html">平均数准确，为什么仍看不见局部过载</a></li><li><a href="/xi-kari-skill/handbook/theory/part-03.html#section-3-4">原文§3.4：D3 尺度变换</a></li><li><a href="/xi-kari-skill/handbook/theory/part-04.html#section-4-18-1">原文§4.18.1：F1 任务恢复</a></li><li><a href="/xi-kari-skill/handbook/theory/part-04.html#section-4-19">原文§4.19：任务族与动态精化</a></li><li><a href="/xi-kari-skill/handbook/theory/part-14.html#section-14-6">原文§14.6：J 轴、O1—O4 与有限授权</a></li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><ol><li>Lisa Bucci, Laura Alaka, Andrew Hagen, Sandy Delgado, Jack Beven. <a href="https://www.nhc.noaa.gov/data/tcr/AL092022_Ian.pdf" target="_blank" rel="noreferrer"><em>National Hurricane Center Tropical Cyclone Report: Hurricane Ian (AL092022), 23–30 September 2022</em></a>. 美国国家飓风中心，2026年3月12日版，72页。封面脚注说明，初版日期为2023年4月2日，本版删去了佛罗里达地面观测部分和补充数据文件中混有实测值与推算值的WeatherStem数据。本页引用第1、4、8—9、15—16、18页和图27（第67页）。</li><li>美国国家飓风中心. <a href="https://web.archive.org/web/20220926140803/https://www.nhc.noaa.gov/aboutcone.shtml" target="_blank" rel="noreferrer">Definition of the NHC Track Forecast Cone</a>. 2022年版，互联网档案馆2022年9月26日存档。其中的定义和大西洋半径也见于John P. Cangialosi, <a href="https://www.nhc.noaa.gov/verification/pdfs/Verification_2021.pdf" target="_blank" rel="noreferrer"><em>National Hurricane Center Forecast Verification Report: 2021 Hurricane Season</em></a>, 2022年4月25日，第13页和表14（第46页）。</li><li>美国国家飓风中心. <a href="https://www.nhc.noaa.gov/archive/2022/al09/al092022.discus.018.shtml" target="_blank" rel="noreferrer">Hurricane Ian Discussion Number 18</a>，2022年9月27日11时（美国东部夏令时）；<a href="https://www.nhc.noaa.gov/archive/2022/al09/al092022.discus.020.shtml" target="_blank" rel="noreferrer">Hurricane Ian Discussion Number 20</a>，同日23时。</li><li>美国国家飓风中心. <a href="https://www.nhc.noaa.gov/aboutcone.shtml" target="_blank" rel="noreferrer">Definition of the NHC Track Forecast Cone</a>. 当前页面，2026年11月12日查阅，所列为2026年的半径。</li></ol>',26)])])}const k=e(n,[["render",i]]);export{f as __pageData,k as default};
